<?php
require_once __DIR__ . '/functions.php';
requireUser();
$genreId = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: 0;
$genreStmt = $pdo->prepare('SELECT genre_id, genre_name, description FROM genres WHERE genre_id = :id'); $genreStmt->execute(['id' => $genreId]); $genre = $genreStmt->fetch();
if (!$genre) { http_response_code(404); exit('Genre not found.'); }
$stmt = $pdo->prepare(trackQuery() . ' JOIN track_genres tg ON tg.track_id = t.track_id WHERE tg.genre_id = :id ORDER BY ar.artist_name, al.title, t.track_number'); $stmt->execute(['id' => $genreId]); $tracks = $stmt->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?php echo e($genre['genre_name']); ?></title><link rel="stylesheet" href="../frontend/user-dashbord.css"><style>.page{max-width:1000px;margin:auto}.panel{background:var(--bg-card);padding:24px;border-radius:14px;margin:20px 0}.row{padding:14px;border-bottom:1px solid var(--border)}.muted{color:var(--text-muted)}a{color:inherit}</style></head><body><main class="main-content page"><p><a href="user-dashbord.php">Home</a></p><section class="panel"><h1><?php echo e($genre['genre_name']); ?></h1><p class="muted"><?php echo e($genre['description']); ?></p><?php foreach ($tracks as $track): ?><div class="row"><a href="track.php?id=<?php echo (int)$track['track_id']; ?>"><?php echo e($track['title']); ?></a> <span class="muted">- <?php echo e($track['artist_name']); ?> / <?php echo e($track['album_title']); ?></span></div><?php endforeach; ?><?php if (!$tracks): ?><p class="muted">No tracks in this genre yet.</p><?php endif; ?></section></main></body></html>
